#include "core/return_service.h"
#include "core/database.h"
#include "core/shift_service.h"
#include <algorithm>
namespace pos {
ReturnService::ReturnService(std::shared_ptr<Database> database):db_(std::move(database)){}
ReturnResult ReturnService::returnSale(const QString& saleId,const QList<ReturnLine>& lines,const QString& reason,bool refundCash){
    if(saleId.isEmpty()||lines.isEmpty()||reason.trimmed().isEmpty())throw DatabaseError("invalid sales return");
    Transaction tx(db_->handle()); auto sale=db_->prepare("SELECT customer_id,status,due_paisa FROM sales WHERE id=?");sale.bind(1,saleId);if(!sale.stepRow()||sale.text(1)=="voided")throw DatabaseError("sale is unavailable");const auto customer=sale.text(0);const auto due=sale.integer(2);const auto returnId=uuid();Money total{};
    auto header=db_->prepare("INSERT INTO sale_returns(id,sale_id,customer_id,status,total_paisa,returned_at,reason) VALUES(?,?,?, 'completed',?,?,?)");header.bind(1,returnId);header.bind(2,saleId);if(customer.isEmpty())header.bindNull(3);else header.bind(3,customer);header.bind(4,0);header.bind(5,utcNow());header.bind(6,reason.trimmed());header.execute();
    for(const auto& line:lines){if(line.itemId.isEmpty()||line.quantity<=0)throw DatabaseError("invalid sales return line");auto item=db_->prepare("SELECT product_id,batch_id,quantity,unit_price_paisa,line_total_paisa FROM sale_items WHERE id=? AND sale_id=?");item.bind(1,line.itemId);item.bind(2,saleId);if(!item.stepRow())throw DatabaseError("sale item not found");const auto product=item.text(0),batch=item.text(1);const auto sold=item.integer(2);auto returned=db_->prepare("SELECT COALESCE(SUM(quantity),0) FROM sale_return_items WHERE sale_item_id=?");returned.bind(1,line.itemId);returned.stepRow();if(line.quantity>sold-returned.integer(0))throw DatabaseError("return quantity exceeds sold quantity");const Money amount=(item.integer(4)*line.quantity)/sold;total+=amount;auto insert=db_->prepare("INSERT INTO sale_return_items(id,return_id,sale_item_id,product_id,batch_id,quantity,amount_paisa) VALUES(?,?,?,?,?,?,?)");insert.bind(1,uuid());insert.bind(2,returnId);insert.bind(3,line.itemId);insert.bind(4,product);if(batch.isEmpty())insert.bindNull(5);else insert.bind(5,batch);insert.bind(6,line.quantity);insert.bind(7,amount);insert.execute();auto stock=db_->prepare("UPDATE products SET stock_quantity=stock_quantity+?,updated_at=? WHERE id=?");stock.bind(1,line.quantity);stock.bind(2,utcNow());stock.bind(3,product);stock.execute();if(!batch.isEmpty()){auto b=db_->prepare("UPDATE batches SET quantity_remaining=quantity_remaining+? WHERE id=?");b.bind(1,line.quantity);b.bind(2,batch);b.execute();}auto movement=db_->prepare("INSERT INTO stock_movements(id,product_id,batch_id,type,quantity,reference_id,reason,balance_after,performed_by,created_at) SELECT ?,?,?, 'sales_return', ?, ?, ?, stock_quantity,'Returns',? FROM products WHERE id=?");movement.bind(1,uuid());movement.bind(2,product);if(batch.isEmpty())movement.bindNull(3);else movement.bind(3,batch);movement.bind(4,line.quantity);movement.bind(5,returnId);movement.bind(6,reason);movement.bind(7,utcNow());movement.bind(8,product);movement.execute();}
    auto setTotal=db_->prepare("UPDATE sale_returns SET total_paisa=? WHERE id=?");setTotal.bind(1,total);setTotal.bind(2,returnId);setTotal.execute();const auto credit=std::min(due,total);if(!customer.isEmpty()&&credit>0){auto update=db_->prepare("UPDATE sales SET due_paisa=due_paisa-? WHERE id=?");update.bind(1,credit);update.bind(2,saleId);update.execute();auto balance=db_->prepare("UPDATE customers SET balance_paisa=balance_paisa-? WHERE id=?");balance.bind(1,credit);balance.bind(2,customer);balance.execute();auto ledger=db_->prepare("INSERT INTO customer_ledger(id,customer_id,sale_id,description,debit_paisa,credit_paisa,running_balance_paisa,created_at) SELECT ?,?,?,'Sales return',0,?,balance_paisa,? FROM customers WHERE id=?");ledger.bind(1,uuid());ledger.bind(2,customer);ledger.bind(3,saleId);ledger.bind(4,credit);ledger.bind(5,utcNow());ledger.bind(6,customer);ledger.execute();}
    const auto cashRefund=refundCash?total-credit:0;if(cashRefund>0){const auto shift=ensureActiveShift(*db_);auto cash=db_->prepare("INSERT INTO cash_transactions(id,shift_id,type,amount_paisa,reason,created_at) VALUES(?,?, 'cash_out',?,?,?)");cash.bind(1,uuid());cash.bind(2,shift);cash.bind(3,cashRefund);cash.bind(4,"Sales return refund");cash.bind(5,utcNow());cash.execute();}tx.commit();return{returnId,total};
}
ReturnResult ReturnService::returnPurchase(const QString& purchaseId,const QList<ReturnLine>& lines,const QString& reason){if(purchaseId.isEmpty()||lines.isEmpty()||reason.trimmed().isEmpty())throw DatabaseError("invalid purchase return");Transaction tx(db_->handle());auto purchase=db_->prepare("SELECT supplier_id,status FROM purchases WHERE id=?");purchase.bind(1,purchaseId);if(!purchase.stepRow()||purchase.text(1)!="completed")throw DatabaseError("purchase is unavailable");const auto supplier=purchase.text(0),returnId=uuid();Money total{};auto header=db_->prepare("INSERT INTO purchase_returns(id,purchase_id,supplier_id,status,total_paisa,returned_at,reason) VALUES(?,?,?,'completed',?,?,?)");header.bind(1,returnId);header.bind(2,purchaseId);header.bind(3,supplier);header.bind(4,0);header.bind(5,utcNow());header.bind(6,reason.trimmed());header.execute();for(const auto& line:lines){if(line.itemId.isEmpty()||line.quantity<=0)throw DatabaseError("invalid purchase return line");auto item=db_->prepare("SELECT product_id,batch_id,quantity,unit_price_paisa,line_total_paisa FROM purchase_items WHERE id=? AND purchase_id=?");item.bind(1,line.itemId);item.bind(2,purchaseId);if(!item.stepRow())throw DatabaseError("purchase item not found");const auto product=item.text(0),batch=item.text(1);const auto received=item.integer(2);auto returned=db_->prepare("SELECT COALESCE(SUM(quantity),0) FROM purchase_return_items WHERE purchase_item_id=?");returned.bind(1,line.itemId);returned.stepRow();if(line.quantity>received-returned.integer(0))throw DatabaseError("return quantity exceeds received quantity");const Money amount=(item.integer(4)*line.quantity)/received;total+=amount;auto insert=db_->prepare("INSERT INTO purchase_return_items(id,return_id,purchase_item_id,product_id,batch_id,quantity,amount_paisa) VALUES(?,?,?,?,?,?,?)");insert.bind(1,uuid());insert.bind(2,returnId);insert.bind(3,line.itemId);insert.bind(4,product);if(batch.isEmpty())insert.bindNull(5);else insert.bind(5,batch);insert.bind(6,line.quantity);insert.bind(7,amount);insert.execute();auto stock=db_->prepare("UPDATE products SET stock_quantity=stock_quantity-?,updated_at=? WHERE id=? AND stock_quantity>=?");stock.bind(1,line.quantity);stock.bind(2,utcNow());stock.bind(3,product);stock.bind(4,line.quantity);stock.execute();if(sqlite3_changes(db_->handle())!=1)throw DatabaseError("insufficient stock for purchase return");if(!batch.isEmpty()){auto b=db_->prepare("UPDATE batches SET quantity_remaining=quantity_remaining-? WHERE id=? AND quantity_remaining>=?");b.bind(1,line.quantity);b.bind(2,batch);b.bind(3,line.quantity);b.execute();if(sqlite3_changes(db_->handle())!=1)throw DatabaseError("insufficient batch stock");}auto movement=db_->prepare("INSERT INTO stock_movements(id,product_id,batch_id,type,quantity,reference_id,reason,balance_after,performed_by,created_at) SELECT ?,?,?, 'purchase_return', ?, ?, ?, stock_quantity,'Returns',? FROM products WHERE id=?");movement.bind(1,uuid());movement.bind(2,product);if(batch.isEmpty())movement.bindNull(3);else movement.bind(3,batch);movement.bind(4,-line.quantity);movement.bind(5,returnId);movement.bind(6,reason);movement.bind(7,utcNow());movement.bind(8,product);movement.execute();}auto setTotal=db_->prepare("UPDATE purchase_returns SET total_paisa=? WHERE id=?");setTotal.bind(1,total);setTotal.bind(2,returnId);setTotal.execute();auto balance=db_->prepare("UPDATE suppliers SET balance_paisa=MAX(0,balance_paisa-?) WHERE id=?");balance.bind(1,total);balance.bind(2,supplier);balance.execute();tx.commit();return{returnId,total};}
}
